	r := moeRouting{tokens: 0, perExpert: make([][]int32, moeExperts), touched: experts}
	for e := 0; e < experts; e++ {
		for i := 0; i < counts[e]; i++ {
			r.perExpert[e] = append(r.perExpert[e], int32(r.tokens))
